static void sh_css_set_dz_config ( struct ia_css_isp_parameters * params , const struct ia_css_dz_config * config ) { assert ( params ) ; IA_CSS_ENTER_PRIVATE ( "dx=%d, dy=%d" , config -> dx , config -> dy ) ; assert ( config -> dx <= HRT_GDC_N ) ; assert ( config -> dy <= HRT_GDC_N ) ; params -> dz_config = * config ; params -> dz_config_changed = true ; params -> isp_params_changed = true ; IA_CSS_LEAVE_PRIVATE ( "void" ) ; } 